| ddl_script                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |
| CREATE TABLE blogs (id uuid NOT NULL DEFAULT gen_random_uuid(), title character varying(255) NOT NULL, slug character varying(255) NOT NULL, excerpt text NOT NULL, content text NOT NULL, category character varying(100) NOT NULL DEFAULT 'Tips Pembelajaran'::character varying, author character varying(100) NOT NULL DEFAULT 'Admin'::character varying, image_url text, status character varying(20) DEFAULT 'published'::character varying, published_at timestamp with time zone DEFAULT timezone('utc'::text, now()), created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));                                                                                                                                                     |
| CREATE TABLE events (id uuid NOT NULL DEFAULT gen_random_uuid(), title character varying(255) NOT NULL, description text, src text NOT NULL, alt character varying(255), badge character varying(100), is_featured boolean DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));                                                                                                                                                                                                                                                                                                                                                                                                                                            |
| CREATE TABLE gallery_items (id uuid NOT NULL DEFAULT gen_random_uuid(), src text NOT NULL, alt character varying(255), caption character varying(255), category character varying(100) NOT NULL DEFAULT 'Umum'::character varying, event_id uuid, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      |
| CREATE TABLE profiles (id uuid NOT NULL, full_name character varying(255) NOT NULL, role character varying(50) DEFAULT 'admin'::character varying, avatar_url text, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| CREATE TABLE programs (id character varying(100) NOT NULL, icon_name character varying(100) NOT NULL, title character varying(255) NOT NULL, color character varying(100) NOT NULL, accent_class character varying(100) NOT NULL, badge_bg character varying(100) NOT NULL, border_accent character varying(100) NOT NULL, description text NOT NULL, order_index integer DEFAULT 0, is_active boolean DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));                                                                                                                                                                                                                                                                |
| CREATE TABLE site_settings (id uuid NOT NULL DEFAULT gen_random_uuid(), key character varying(100) NOT NULL, value text NOT NULL, label character varying(250), updated_at timestamp with time zone DEFAULT now());                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
| CREATE TABLE sub_programs (id uuid NOT NULL DEFAULT gen_random_uuid(), program_id character varying(100), name character varying(255) NOT NULL, description text NOT NULL, badge character varying(100), harga_daftar bigint, spp_bulanan bigint, spp_label character varying(100), spp_note character varying(255), harga_modul bigint, harga_ujian bigint, jadwal character varying(255), materi ARRAY DEFAULT '{}'::text[], order_index integer DEFAULT 0, is_active boolean DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), module_images ARRAY DEFAULT '{}'::text[], is_discount_active boolean DEFAULT false, discount_percentage integer DEFAULT 0, harga_daftar_discount bigint, spp_bulanan_discount bigint); |
| CREATE TABLE team (id bigint NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), name character varying NOT NULL, role character varying, description text, image_url text, order_index bigint DEFAULT '0'::bigint, is_active boolean DEFAULT true, type character varying(50) DEFAULT 'teacher'::character varying, subject_category ARRAY);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            |		